132	bool DiskWebServer::exists(const String & path) const
133	{
134	    LOG_TRACE(&Poco::Logger::get("DiskWeb"), "Checking existence of path: {}", path);
135	
136	    if (files.find(path) != files.end())
137	        return true;
138	
139	    if (path.ends_with(MergeTreeData::FORMAT_VERSION_FILE_NAME) && files.find(fs::path(path).parent_path() / "") == files.end())
140	    {
141	        try
142	        {
143	            initialize(fs::path(url) / fs::path(path).parent_path());
144	            return files.find(path) != files.end();
145	        }
146	        catch (...)
147	        {
148	            const auto message = getCurrentExceptionMessage(false);
149	            bool can_throw = CurrentThread::isInitialized() && CurrentThread::get().getQueryContext();
150	            if (can_throw)
151	                throw Exception(ErrorCodes::NETWORK_ERROR, "Cannot load disk metadata. Error: {}", message);
152	
153	            LOG_TRACE(&Poco::Logger::get("DiskWeb"), "Cannot load disk metadata. Error: {}", message);
154	            return false;
155	        }
156	    }
157	
158	    return false;
159	}
